{
  "query": "mutation RegisterUser($input: RegisterInput!) { registerUser(input: $input) { success message user { id username email role fullName } token } }",
  "variables": {
    "input": {
      "username": "{{username}}",
      "email": "{{email}}",
      "password": "{{password}}",
      "firstName": "{{firstName}}",
      "lastName": "{{lastName}}"
    }
  }
}

{
  "query": "mutation LoginUser($input: LoginInput!) { loginUser(input: $input) { success message user { id username email role } token } }",
  "variables": {
    "input": {
      "usernameOrEmail": "{{usernameOrEmail}}",
      "password": "{{password}}"
    }
  }
}

{
  "query": "query GetCurrentUser { me { id username email role fullName createdAt lastLogin } }"
}

{
  "query": "query GetSensors { sensors { id name model isActive currentLocation { id name } lastReading { id readingTime humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } } }"
}

{
  "query": "query GetSensor($id: Int!) { sensor(id: $id) { id name model isActive currentLocation { name } readings { id readingTime humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } } }",
  "variables": {
    "id": {{sensorId}}
  }
}

{
  "query": "query GetLocations { locations { id name description currentSensors { id name model isActive } } }"
}

{
  "query": "query GetLocation($id: Int!) { location(id: $id) { id name description currentSensors { id name model } readings { id readingTime sensor { name } humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } } }",
  "variables": {
    "id": {{locationId}}
  }
}

{
  "query": "mutation CreateSensorReading($input: CreateSensorReadingInput!) { createSensorReading(input: $input) { success message errors sensorReading { id readingTime sensor { name } humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } } }",
  "variables": {
    "input": {
      "sensorId": {{sensorId}},
      "humidityPercentage": {{humidityPercentage}},
      "temperatureCelsius": {{temperatureCelsius}},
      "co2Ppm": {{co2Ppm}}
    }
  }
}

{
  "query": "query GetRecentReadings { sensorReadings { id readingTime sensor { name model } location { name } humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } }"
}

{
  "query": "query GetFilteredReadings($filters: SensorDataFilterInput!) { filteredSensorReadings(filters: $filters) { id readingTime sensor { name } location { name } humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } }",
  "variables": {
    "filters": {
      "startDate": "{{startDate}}",
      "endDate": "{{endDate}}",
      "orderBy": "reading_time",
      "orderDirection": "desc",
      "limit": 100
    }
  }
}

{
  "query": "query GetFilteredReadings($filters: SensorDataFilterInput!) { filteredSensorReadings(filters: $filters) { id readingTime sensor { name } location { name } humidityReading { humidityPercentage } temperatureReading { temperatureCelsius } co2Reading { co2Ppm } } }",
  "variables": {
    "filters": {
      "locationIds": [{{locationId}}],
      "orderBy": "reading_time",
      "orderDirection": "desc",
      "limit": 50
    }
  }
}

{
  "query": "query GetHighCO2Readings($filters: SensorDataFilterInput!) { filteredSensorReadings(filters: $filters) { id readingTime sensor { name } location { name } co2Reading { co2Ppm } } }",
  "variables": {
    "filters": {
      "minCo2Ppm": 1000,
      "orderBy": "co2_ppm",
      "orderDirection": "desc",
      "limit": 50
    }
  }
}

{
  "query": "query GetTemperatureRangeReadings($filters: SensorDataFilterInput!) { filteredSensorReadings(filters: $filters) { id readingTime sensor { name } location { name } temperatureReading { temperatureCelsius } } }",
  "variables": {
    "filters": {
      "minTemperatureCelsius": {{minTemp}},
      "maxTemperatureCelsius": {{maxTemp}},
      "orderBy": "temperature_celsius",
      "orderDirection": "desc",
      "limit": 100
    }
  }
}

{
  "query": "query GetAllUsers { users { id username email role fullName isActive createdAt lastLogin } }"
}

{
  "query": "query GetUser($id: Int!) { user(id: $id) { id username email role fullName isActive createdAt lastLogin } }",
  "variables": {
    "id": {{userId}}
  }
}
